CREATE TABLE "job_resource_requirements" ("id" TEXT NOT NULL, "job_id" TEXT NOT NULL, "resource_type" TEXT NOT NULL, "name" TEXT NOT NULL, "quantity" DOUBLE PRECISION, "unit" TEXT, "requirement_status" TEXT NOT NULL DEFAULT 'needed', "estimated_cost" DOUBLE PRECISION, "actual_cost" DOUBLE PRECISION, "notes" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "job_resource_requirements_pkey" PRIMARY KEY ("id")); CREATE INDEX "job_resource_requirements_job_id_idx" ON "job_resource_requirements"("job_id"); ALTER TABLE "job_resource_requirements" ADD CONSTRAINT "job_resource_requirements_job_id_fkey" FOREIGN KEY ("job_id") REFERENCES "jobs"("id") ON DELETE CASCADE ON UPDATE CASCADE;
